      public void addRelationship(Relationship relationship) {
              Object type = relationship.getType();
              if (RelTypes.isMono(type)) {
                       for (AvailabilityPool pool : monoPools) {
                              pool.remove(myPerson);
                       }
                       for (AvailabilityPool pool : polyPools) {
                              pool.remove(myPerson);
                       }
                       monoShip = relationship;
              } else if (RelTypes.isPoly(type)) {
                       polyShips.add(relationship);
             } else if (RelTypes.isCasual(type)) {
                       casualShip = relationship;
              }
      }

      public void breakOff(Relationship relationship) {
              Object type = relationship.getType();
              if (RelTypes.isMono(type)) {
                       for (AvailabilityPool pool : monoPools) {
                              pool.add(myPerson);
                       }
                       for (AvailabilityPool pool : polyPools) {
                              pool.add(myPerson);
                       }
                       monoShip = null;
              } else if (RelTypes.isPoly(type)) {
                       polyShips.remove(relationship);
              } else if (RelTypes.isCasual(type)) {
                       casualShip = null;
              }
      }
